mapper.select:
SELECT o.*, (SELECT COUNT(*) FROM order_item WHERE order_id = o.order_id) as itemCount, (SELECT product_image FROM order_item WHERE order_id = o.order_id LIMIT 1) as firstItemImage FROM `order` o WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.created_at DESC

SELECT o.order_id, o.order_no, o.status, CASE o.status WHEN 0 THEN '待支付' WHEN 1 THEN '已支付' WHEN 2 THEN '已发货' WHEN 3 THEN '已完成' WHEN 4 THEN '已取消' ELSE '未知状态' END as status_desc, o.total_amount, o.payment_amount, o.created_at, (SELECT COUNT(*) FROM order_item WHERE order_id = o.order_id) as item_count, (SELECT COUNT(*) FROM product_review WHERE order_id = o.order_id AND user_id = o.user_id) as reviewed_count, CASE WHEN o.status != 3 THEN 0 WHEN (SELECT COUNT(*) FROM order_item WHERE order_id = o.order_id) = (SELECT COUNT(*) FROM product_review WHERE order_id = o.order_id AND user_id = o.user_id) THEN 1 ELSE 0 END as all_reviewed, oi.product_id, oi.product_name, oi.product_image, oi.quantity, oi.current_price FROM `order` o LEFT JOIN ( SELECT order_id, product_id, product_name, product_image, quantity, current_price, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY item_id) as rn FROM order_item ) oi ON o.order_id = oi.order_id AND oi.rn <= 3 WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.created_at DESC, oi.rn

SELECT o.order_id, o.order_no, o.user_id, u.username, u.phone, o.status, CASE o.status WHEN 0 THEN '待支付' WHEN 1 THEN '已支付' WHEN 2 THEN '已发货' WHEN 3 THEN '已完成' WHEN 4 THEN '已取消' ELSE '未知状态' END as status_desc, o.total_amount, o.payment_amount, o.payment_type, CASE o.payment_type WHEN 1 THEN '支付宝' WHEN 2 THEN '微信支付' WHEN 3 THEN '余额支付' ELSE NULL END as payment_type_desc, ua.receiver_name, ua.receiver_phone, (SELECT COUNT(*) FROM order_item WHERE order_id = o.order_id) as item_count, o.payment_time, o.delivery_time, o.created_at FROM `order` o LEFT JOIN user u ON o.user_id = u.user_id LEFT JOIN user_address ua ON o.address_id = ua.address_id
AND o.status = #{status}
AND o.created_at >= #{startTime}
AND o.created_at <= #{endTime}
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') OR ua.receiver_name LIKE CONCAT('%', #{keyword}, '%') OR ua.receiver_phone LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY o.created_at DESC

mapper.update:
UPDATE `order` 
SET status = #{status}, version = version + 1
WHERE order_no = #{orderNo} AND version = #{version}
